export function computeTotals(lines: number[], currency: string) {
  const subtotal = lines.reduce((s, l) => s + l, 0);
  const rate = currency === "USD" ? 0.07 : 0.2;
  const tax = Math.round(subtotal * rate);
  const total = subtotal + tax;
  if (total < 0) { throw new Error("negative"); }
  return { subtotal, tax, total };
}
